<?php
require_once __DIR__.'/includes/layout.php';
require_once __DIR__.'/includes/import_csv.php';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='import_csv') importer('loc','loc.php');
require_role(['SO','THU_KY']);
if($_SERVER['REQUEST_METHOD']==='POST')task('loc.php',function(PDO $db,array $u){$action=val('action');if($action==='score'&&$u['vai_tro']!=='THU_KY')throw new RuntimeException('Chỉ thư ký được nhập điểm đã thống nhất.');if($action==='lock'&&$u['vai_tro']!=='SO')throw new RuntimeException('Chỉ người có thẩm quyền thuộc Sở được chốt điểm.');$phach=required_val('ma_phach');$db->beginTransaction();try{$q=$db->prepare('SELECT b.ma_bai,b.da_thong_nhat_diem,pc.trang_thai FROM bai_thi b JOIN tui_bai_thi t ON b.ma_tui=t.ma_tui JOIN phan_cong_cham_thi pc ON pc.ma_tui=t.ma_tui WHERE b.ma_phach=? FOR UPDATE');$q->execute([$phach]);$paper=$q->fetch();if(!$paper)throw new RuntimeException('Mã phách không tồn tại hoặc túi bài chưa có phân công chấm thi.');if($action==='score'){if(!(int)$paper['da_thong_nhat_diem'])throw new RuntimeException('Chưa có xác nhận hai cán bộ đã đối chiếu, thống nhất điểm.');$score=filter_var(val('diem'),FILTER_VALIDATE_FLOAT);if($score===false||$score<0||$score>10)throw new RuntimeException('Điểm phải trong khoảng 0–10.');$q=$db->prepare('INSERT INTO diem_thi(ma_bai,diem,nguoi_nhap) VALUES(?,?,?)');$q->execute([$paper['ma_bai'],$score,$u['id']]);audit($db,$u['id'],'NHAP_DIEM',$phach.' = '.$score);}
 elseif($action==='lock'){$q=$db->prepare("UPDATE diem_thi SET trang_thai='DA_CHOT',nguoi_chot=?,ngay_chot=NOW() WHERE ma_bai=? AND trang_thai='DA_NHAP'");$q->execute([$u['id'],$paper['ma_bai']]);if(!$q->rowCount())throw new RuntimeException('Điểm chưa được nhập hoặc đã chốt.');audit($db,$u['id'],'CHOT_DIEM',$phach);}else throw new RuntimeException('Thao tác không hợp lệ.');$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}});
page_start('Cập nhật điểm thi theo mã phách','loc');echo '<div class="note">QT07–08: Chỉ thư ký được nhập điểm <b>một lần</b> theo mã phách, khi hai cán bộ đã thống nhất. Phải chốt điểm trước khi cho phép ghép phách; màn hình này không hiển thị SBD, tên thí sinh hay quan hệ ánh xạ phách–SBD.</div><div class="panel"><h2>Nhập điểm chính thức</h2>';form_open();echo '<input type="hidden" name="action" value="score">';field('ma_phach','Mã phách');field('diem','Điểm chính thức (0–10)','number',true,'min="0" max="10" step="0.01"');form_close('Lưu điểm một lần');echo '</div><div class="panel"><h2>Chốt một điểm đã nhập (Sở)</h2>';form_open();echo '<input type="hidden" name="action" value="lock">';field('ma_phach','Mã phách');form_close('Xác nhận chốt điểm');echo '</div><div class="panel"><h2>Điểm theo mã phách</h2>';table_rows(db()->query('SELECT b.ma_phach,m.ten_mon,d.diem,d.trang_thai,d.ngay_nhap FROM diem_thi d JOIN bai_thi b ON d.ma_bai=b.ma_bai JOIN tui_bai_thi t ON b.ma_tui=t.ma_tui JOIN mon_thi m ON m.ma_mon=t.ma_mon ORDER BY d.ngay_nhap DESC')->fetchAll(),['Mã phách','Môn','Điểm','Trạng thái','Ngày nhập']);echo '</div>';import_panel('loc','Điểm thi theo mã phách');page_end();
